# Ported from modern-debian-tools-python-debug/host-setup/scripts/
# mdt-apply-dev-caps.sh's cgroup2-mount-flags section (the *already-fixed*
# copy, CGROUP2_FLAGS=fix default) rather than reproduced inline in a unit's
# ExecStart= (which would need every '$' doubled to '$$' for systemd's own
# specifier expansion — a real script file avoids that entirely and stays
# byte-for-byte diffable against the source it was ported from).
#
# Unlike host-setup's version, this has no periodic timer behind it — a
# fresh install only gets one shot at boot, so this errs toward being
# unconditionally safe to re-run (idempotent: a no-op once both options are
# already present) rather than toward matching host-setup's sweep cadence.
CGROUP2_FLAGS_SCRIPT = """\
#!/bin/sh
# Restores memory_recursiveprot (+nsdelegate) on /sys/fs/cgroup if a later
# remount stripped it — systemd mounts cgroup2 with these by default at boot
# (>= 248), but a runtime remount from the init cgroup namespace can silently
# drop them, and without memory_recursiveprot every slice's MemoryLow/
# MemoryMin becomes a no-op while `systemctl show` keeps reporting the value
# you set. Also restores memory_hugetlb_accounting on kernel >= 6.6 (a
# systemd >= 260 mount default we can take at the raw kernel-mount-option
# level without waiting for systemd to reach that version) — kernel-gated
# because offering an unsupported mount option fails the WHOLE remount, not
# just that one option.
set -eu

CG=/sys/fs/cgroup
KVER=$(uname -r | grep -oE '^[0-9]+\\.[0-9]+')
KMAJOR=${KVER%%.*}
KMINOR=${KVER##*.}
HUGETLB_OPT=""
if [ -n "$KMAJOR" ] && [ -n "$KMINOR" ] \\
   && { [ "$KMAJOR" -gt 6 ] || { [ "$KMAJOR" -eq 6 ] && [ "$KMINOR" -ge 6 ]; }; }; then
  HUGETLB_OPT=",memory_hugetlb_accounting"
fi

CG_OPTS=$(findmnt -no OPTIONS "$CG" 2>/dev/null || true)
MISSING=0
if [ -n "$CG_OPTS" ]; then
  case "$CG_OPTS" in *memory_recursiveprot*) : ;; *) MISSING=1 ;; esac
  if [ -n "$HUGETLB_OPT" ]; then
    case "$CG_OPTS" in *memory_hugetlb_accounting*) : ;; *) MISSING=1 ;; esac
  fi
fi
if [ "$MISSING" = 1 ]; then
  mount -o "remount,nsdelegate,memory_recursiveprot$HUGETLB_OPT" "$CG"
  echo "cgroup2: restored nsdelegate,memory_recursiveprot$HUGETLB_OPT (was: $CG_OPTS)"
fi
"""


CGROUP2_FLAGS_SERVICE = """\
[Unit]
Description=Restore cgroup2 memory_recursiveprot (+nsdelegate, +memory_hugetlb_accounting)
DefaultDependencies=no
After=local-fs.target
Before=sysinit.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/vbpub-cgroup2-flags.sh

[Install]
WantedBy=sysinit.target
"""


# Ported from gstammtisch-guide/files/etc/tmpfiles.d/ksm.conf, but as a
# oneshot service (like ZSWAP_SERVICE/THP_SERVICE) rather than a tmpfiles.d
# `w` line — debian-install-v2 doesn't use tmpfiles.d anywhere else, and this
# keeps every early-boot sysfs tuning knob behind the same mechanism.
# ksmd stays idle and costs ~nothing until a process opts in via
# prctl(PR_SET_MEMORY_MERGE, 1) — this only turns the scanner on, it merges
# nothing by itself; not game-specific (the opt-in is what's game-specific).
KSM_SERVICE = """\
[Unit]
Description=Enable Kernel Samepage Merging (KSM)
DefaultDependencies=no
After=sysinit.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/sh -c 'echo 1 > /sys/kernel/mm/ksm/run || true'
ExecStart=/bin/sh -c 'echo scan-time > /sys/kernel/mm/ksm/advisor_mode || true'
ExecStart=/bin/sh -c 'echo 200 > /sys/kernel/mm/ksm/advisor_target_scan_time || true'
ExecStart=/bin/sh -c 'echo 1 > /sys/kernel/mm/ksm/use_zero_pages || true'

[Install]
WantedBy=sysinit.target
"""


# Ported from gstammtisch-guide/files/etc/systemd/oomd.conf.d/gstammtisch.conf
# (global thresholds only) — the per-slice ManagedOOMMemoryPressure=kill
# piece stays with mdt host-setup's dev-tier slices, out of scope here. This
# is the safety net that makes any vm.swappiness value safe to run
# unattended: swap-based kill fires system-wide without needing per-unit
# opt-in; pressure-based kill only fires for cgroups that opt in elsewhere.
OOMD_CONFIG = """\
# /etc/systemd/oomd.conf.d/vbpub.conf
[OOM]
SwapUsedLimit=90%
DefaultMemoryPressureLimit=60%
DefaultMemoryPressureDurationSec=20s
"""


# Debian ships fstrim.timer (util-linux) at OnCalendar=weekly; this overrides
# it to daily for this fleet's thin-provisioned virtual disks. A drop-in, not
# a hand-authored timer, so `apt` upgrades to the packaged unit keep working.
# Covers root + swap + everything else mounted — batched TRIM, not the
# continuous `discard` mount option (which has its own latency history).
FSTRIM_OVERRIDE = """\
[Timer]
OnCalendar=
OnCalendar=daily
"""


# Reusable Telegram notifier — any unit/timer/script can call this instead of
# each owning its own HTTP call. Reads the same credential pair
# debian-install-v2 itself already writes to /etc/vbpub/credentials/ for
# EITHER credential_mode (root-storage: read directly; systemd: a caller unit
# with LoadCredential= gets the same two files copied into
# $CREDENTIALS_DIRECTORY at start, which this script prefers when set).
NOTIFY_SCRIPT = """\
#!/bin/sh
# /usr/local/sbin/vbpub-notify MESSAGE
set -eu

CRED_DIR="${CREDENTIALS_DIRECTORY:-/etc/vbpub/credentials}"
TOKEN_FILE="$CRED_DIR/telegram_bot_token"
CHAT_FILE="$CRED_DIR/telegram_chat_id"

if [ ! -s "$TOKEN_FILE" ] || [ ! -s "$CHAT_FILE" ]; then
  echo "vbpub-notify: no Telegram credentials at $CRED_DIR, skipping" >&2
  exit 0
fi

TOKEN=$(cat "$TOKEN_FILE")
CHAT_ID=$(cat "$CHAT_FILE")
MESSAGE="${1:?usage: vbpub-notify MESSAGE}"

curl -fsS --max-time 15 \\
  --data-urlencode "chat_id=${CHAT_ID}" \\
  --data-urlencode "text=${MESSAGE}" \\
  "https://api.telegram.org/bot${TOKEN}/sendMessage" >/dev/null \\
  || echo "vbpub-notify: send failed" >&2
"""


# Age-filtered only; never touches `docker volume prune` / `--volumes` —
# Wings bind-mounts /var/lib/pterodactyl/volumes/<uuid> by host path for all
# server state, so nothing durable is reachable through Docker's volume
# subsystem at all. That's a structural exclusion, not a filter to get
# right. Stopped containers carry no state Wings can't recreate from its own
# persisted config (wings.db) on next start.
DOCKER_CLEANUP_SERVICE = """\
[Unit]
Description=Prune aged Docker images, stopped containers, and build cache
After=docker.service
Requires=docker.service

[Service]
Type=oneshot
ExecStart=/usr/bin/docker container prune -f --filter until={age_hours}h
ExecStart=/usr/bin/docker image prune -af --filter until={age_hours}h
ExecStart=/usr/bin/docker builder prune -af --filter until={age_hours}h
"""

