# Fixed /etc/vbpub/ path, not the configurable state_dir — matches the
# existing convention (bootstrap.env, credentials/ already live there
# regardless of state_dir). Runs once daily in the configured maintenance
# window; a no-op unless /var/run/reboot-required is present (dpkg's
# standard signal, shipped once update-notifier-common — an
# unattended-upgrades dependency — is installed).
REBOOT_CHECK_SCRIPT = """\
#!/bin/sh
# /usr/local/sbin/vbpub-reboot-check
set -eu

if [ ! -e /var/run/reboot-required ]; then
  exit 0
fi

PKGS=""
if [ -s /var/run/reboot-required.pkgs ]; then
  PKGS=$(tr '\\n' ' ' < /var/run/reboot-required.pkgs)
fi
MSG="vbpub: rebooting now for pending updates"
if [ -n "$PKGS" ]; then
  MSG="$MSG ($PKGS)"
fi
/usr/local/sbin/vbpub-notify "$MSG"
mkdir -p /etc/vbpub
touch /etc/vbpub/rebooted-for-updates
/usr/bin/systemctl reboot
"""

REBOOT_CHECK_SERVICE = """\
[Unit]
Description=Reboot for pending updates if required (maintenance window)

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/vbpub-reboot-check
"""

# Persistent=false: a missed daily check (host was off) should not fire an
# immediate surprise reboot on next boot — only within its intended window.
REBOOT_CHECK_TIMER = """\
[Unit]
Description=Daily reboot-required check ({time} maintenance window)

[Timer]
OnCalendar=*-*-* {time}:00
RandomizedDelaySec=300
Persistent=false

[Install]
WantedBy=timers.target
"""

